insert into public.quiz_questions (
  external_id, test_id, test_title, category, block_id, block_range, topic, situation,
  question_number, prompt, options, correct_answer, explanation, option_feedback, sequence, active
)
select
  new_questions.external_id,
  new_questions.test_id,
  new_questions.test_title,
  'especificos',
  new_questions.block_id,
  new_questions.block_range,
  new_questions.topic,
  new_questions.situation,
  new_questions.question_number,
  new_questions.prompt,
  new_questions.options,
  new_questions.correct_answer,
  new_questions.explanation,
  new_questions.option_feedback,
  base_sequence.value + new_questions.position,
  true
from new_questions
cross join base_sequence
on conflict (external_id) do update set
  test_id = excluded.test_id,
  test_title = excluded.test_title,
  category = excluded.category,
  block_id = excluded.block_id,
  block_range = excluded.block_range,
  topic = excluded.topic,
  situation = excluded.situation,
  question_number = excluded.question_number,
  prompt = excluded.prompt,
  options = excluded.options,
  correct_answer = excluded.correct_answer,
  explanation = excluded.explanation,
  option_feedback = excluded.option_feedback,
  sequence = excluded.sequence,
  active = true;

update public.quiz_questions
set
  options = jsonb_build_array(options ->> 1, options ->> 0, options ->> 2),
  option_feedback = jsonb_build_array(option_feedback ->> 1, option_feedback ->> 0, option_feedback ->> 2),
  correct_answer = 1
where external_id in (
  'gen-chem-27', 'gen-chem-30', 'gen-chem-33', 'gen-chem-36', 'gen-chem-39', 'gen-chem-42', 'gen-chem-45',
  'gen-nat-27', 'gen-nat-30', 'gen-nat-33', 'gen-nat-36', 'gen-nat-39', 'gen-nat-42', 'gen-nat-45'
);

