set
  options = jsonb_build_array(options ->> 1, options ->> 2, options ->> 0),
  option_feedback = jsonb_build_array(option_feedback ->> 1, option_feedback ->> 2, option_feedback ->> 0),
  correct_answer = 2
where external_id in (
  'gen-chem-28', 'gen-chem-31', 'gen-chem-34', 'gen-chem-37', 'gen-chem-40', 'gen-chem-43', 'gen-chem-46',
  'gen-nat-28', 'gen-nat-31', 'gen-nat-34', 'gen-nat-37', 'gen-nat-40', 'gen-nat-43', 'gen-nat-46'
);
